const messages = {
  en: enMessages,
  ru: ruMessages,
  zh: zhMessages,
  es: esMessages,
  pt: ptMessages,
  fr: frMessages,
  it: itMessages,
  de: deMessages,
  ja: jaMessages,
  ko: koMessages,
  ar: arMessages,
  hi: hiMessages,
  tr: trMessages,
} satisfies Record<UiLanguage, Record<TranslationKey, string>>

type Translate = (key: TranslationKey, values?: Record<string, string | number>) => string

interface I18nValue {
  language: UiLanguage
  setLanguage: (language: UiLanguage) => void
  t: Translate
}

// Browser locale → supported UI language. First prefix match wins; 'en' is
// the catch-all fallback for anything we don't ship.
const NAV_LOCALE_PREFIXES: ReadonlyArray<readonly [string, UiLanguage]> = [
  ['zh', 'zh'],
  ['ru', 'ru'],
  ['es', 'es'],
  ['pt', 'pt'],
  ['fr', 'fr'],
  ['it', 'it'],
  ['de', 'de'],
  ['ja', 'ja'],
  ['ko', 'ko'],
  ['ar', 'ar'],
  ['hi', 'hi'],
  ['tr', 'tr'],
]

const getInitialLanguage = (): UiLanguage => {
  if (typeof window === 'undefined') return 'en'
  const stored = readStoredLanguage()
  if (stored) return stored
  const nav = window.navigator.language.toLowerCase()
  const hit = NAV_LOCALE_PREFIXES.find(([prefix]) => nav.startsWith(prefix))
  return hit ? hit[1] : 'en'
}

const readStoredLanguage = (): UiLanguage | null => {
  try {
    const stored = window.localStorage.getItem(UI_LANGUAGE_STORAGE_KEY)
    return isUiLanguage(stored) ? stored : null
  } catch {
    return null
  }
}

const writeStoredLanguage = (language: UiLanguage) => {
  try {
    window.localStorage.setItem(UI_LANGUAGE_STORAGE_KEY, language)
  } catch {
    // Language switching should still work for this session when storage is unavailable.
  }
}

const createTranslator =
  (language: UiLanguage): Translate =>
  (key, values = {}) =>
    messages[language]?.[key]?.replace(/\{(\w+)\}/g, (match, name: string) => {
      const value = values[name]
      return value === undefined ? match : String(value)
    })

const fallbackValue: I18nValue = {
  language: 'en',
  setLanguage: () => {},
  t: createTranslator('en'),
}

const I18nContext = createContext<I18nValue>(fallbackValue)

export const I18nProvider = ({ children }: { children: ReactNode }) => {
  const [language, setLanguageState] = useState<UiLanguage>(getInitialLanguage)

  const value = useMemo<I18nValue>(() => {
    const setLanguage = (nextLanguage: UiLanguage) => {
      setLanguageState(nextLanguage)
      writeStoredLanguage(nextLanguage)
    }
    return {
      language,
      setLanguage,
      t: createTranslator(language),
    }
  }, [language])

  return <I18nContext.Provider value={value}>{children}</I18nContext.Provider>
}

export const useI18n = (): I18nValue => useContext(I18nContext)
